def transform(grid):
    rows, cols = len(grid), len(grid[0])
    # Collect constraints from non-zero input cells
    constraints = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                constraints.append((r, c, grid[r][c]))

    # Determine if the grid follows a "Solid" pattern (filled rows) or "Sparse" pattern
    # A row is mixed if it contains at least one 0 and at least one non-0 value.
    # If ANY row is mixed, the grid is considered Sparse. Otherwise, solid.
    is_solid = True
    for r in range(rows):
        row = grid[r]
        has_zero = any(x == 0 for x in row)
        has_nonzero = any(x != 0 for x in row)
        if has_zero and has_nonzero:
            is_solid = False
            break

    # Iterate to find the smallest Period P that explains all constraints
    P = 1
    mapping = {}
    found_P = False

    for p in range(1, 40):
        mapping = {}
        valid = True
        for r, c, v in constraints:
            # Calculate key based on pattern type
            if is_solid:
                key = r % p
            else:
                key = (r + c) % p

            if key in mapping:
                if mapping[key] != v:
                    valid = False
                    break
            else:
                mapping[key] = v

        if valid:
            P = p
            found_P = True
            break

    # If no P found (default if loop fails or constraint logic is complex), use 1
    if not found_P:
        P = 1
        # Try to build mapping for P=1 anyway to avoid total failure
        mapping = {}
        for r, c, v in constraints:
            key = r % P if is_solid else (r + c) % P
            mapping[key] = v

    # Generate output grid using the found Period and mapping
    result = []
    for r in range(rows):
        row_data = []
        for c in range(cols):
            if is_solid:
                key = r % P
            else:
                key = (r + c) % P

            # Retrieve value, default to 0 if key not in mapping
            val = mapping.get(key, 0)
            row_data.append(val)
        result.append(row_data)

    return result
